-- Quest tracker objective text: reported by Four, 2026-11-23 (Pilgrim's Bounty "Spice Bread Stuffing" and
-- "Pumpkin Pie" showed "2/5 Spice Bread Stuffing Proxy slain" above the real "2/5 Spice Bread Stuffing").
-- When a kill-credit or event objective has no Description the client builds one from the credit
-- creature's name ("<bunny> slain"). Our dump left Description empty on 9,147 objectives that TDB 8.3.7
-- fills (e.g. 'Prepare Spice Bread Stuffing', 'Freed Proto-Drakes', 'Mal''Ganis Defeated'). This copies
-- TDB's text, matched on objective ID, QuestID, Type and ObjectID, only where ours is empty.
-- The client caches quest text: delete the client's Cache folder after applying.
DROP TEMPORARY TABLE IF EXISTS `zr_qobj_desc`;
CREATE TEMPORARY TABLE `zr_qobj_desc` (`ID` INT UNSIGNED PRIMARY KEY,`QuestID` INT UNSIGNED,`Type` TINYINT UNSIGNED,`ObjectID` INT,`Description` TEXT);
